insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Trebam li rezervirati stol?', 'Do I need to book a table?', 'Muss ich einen Tisch reservieren?', 'Od lipnja do rujna da, posebno za terasu u vrijeme zalaska sunca. Izvan sezone obično imamo slobodan stol, ali rezervacija vam čuva mjesto uz more.', 'From June to September, yes, especially for the terrace at sunset. Outside those months we usually have a free table, but booking keeps you a seat by the water.', 'Von Juni bis September ja, besonders für die Terrasse zum Sonnenuntergang. In der Nebensaison haben wir meist einen freien Tisch, aber mit Reservierung sitzen Sie sicher am Wasser.', 0);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Primate li veće grupe?', 'Can you seat large groups?', 'Nehmen Sie größere Gruppen auf?', 'Da, do 30 osoba na terasi. Za grupe od 9 ili više osoba odaberite opciju za veliku grupu u obrascu i javit ćemo vam se s prijedlogom menija.', 'Yes, up to 30 guests on the terrace. For 9 or more, tick the large-group option in the booking form and we will reply with a set menu suggestion.', 'Ja, bis zu 30 Gäste auf der Terrasse. Ab 9 Personen wählen Sie im Formular die Option für große Gruppen, wir melden uns mit einem Menüvorschlag.', 1);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Jesu li djeca dobrodošla?', 'Are children welcome?', 'Sind Kinder willkommen?', 'Naravno. Imamo dječje stolice i manje porcije ribe i tjestenine.', 'Of course. We have high chairs and smaller portions of fish and pasta.', 'Natürlich. Wir haben Kinderhochstühle und kleinere Portionen Fisch und Pasta.', 2);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Mogu li doći sa psom?', 'Can I bring my dog?', 'Darf ich meinen Hund mitbringen?', 'Psi su dobrodošli na terasi. Donijet ćemo posudu s vodom.', 'Dogs are welcome on the terrace. We will bring a bowl of water.', 'Hunde sind auf der Terrasse willkommen. Wir bringen eine Schale Wasser.', 3);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Gdje mogu parkirati?', 'Where can I park?', 'Wo kann ich parken?', 'Na javnom parkiralištu iznad uvale, tri minute hoda do nas. U srpnju i kolovozu parking se plaća 2 € na sat.', 'In the public car park above the cove, a three-minute walk down to us. In July and August it costs €2 per hour.', 'Auf dem öffentlichen Parkplatz oberhalb der Bucht, drei Gehminuten entfernt. Im Juli und August kostet er 2 € pro Stunde.', 4);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Mogu li platiti karticom?', 'Can I pay by card?', 'Kann ich mit Karte bezahlen?', 'Da, primamo sve veće kartice i Apple Pay te Google Pay.', 'Yes, we take all major cards, Apple Pay and Google Pay.', 'Ja, wir akzeptieren alle gängigen Karten sowie Apple Pay und Google Pay.', 5);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Možete li prilagoditi jela alergijama?', 'Can you cook around allergies?', 'Können Sie auf Allergien eingehen?', 'Da. Na jelovniku su označena veganska i bezglutenska jela, a kuhinja može prilagoditi većinu ostalih. Recite nam pri rezervaciji ili konobaru.', 'Yes. Vegan and gluten-free dishes are marked on the menu, and the kitchen can adapt most others. Tell us in your booking note or tell your waiter.', 'Ja. Vegane und glutenfreie Gerichte sind auf der Karte markiert, die Küche passt die meisten anderen an. Geben Sie es bei der Reservierung an oder sagen Sie es unserem Service.', 6);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Kada ste otvoreni?', 'When are you open?', 'Wann haben Sie geöffnet?', 'Od 1. travnja do 31. listopada. Ljeti (15. 6. – 15. 9.) svaki dan od 11 do 24 h, u proljeće i jesen od 12 do 22 h, ponedjeljkom zatvoreno. Zimi je konoba zatvorena.', 'From 1 April to 31 October. In summer (15 June – 15 September) daily from 11:00 to midnight; in spring and autumn from 12:00 to 22:00, closed Mondays. We close for the winter.', 'Vom 1. April bis 31. Oktober. Im Sommer (15. Juni – 15. September) täglich 11–24 Uhr, im Frühling und Herbst 12–22 Uhr, montags Ruhetag. Im Winter geschlossen.', 7);
insert into faqs (site_id, question_hr, question_en, question_de, answer_hr, answer_en, answer_de, sort) values ('konoba', 'Mogu li doći brodom?', 'Can I arrive by boat?', 'Kann ich mit dem Boot kommen?', 'Da. Imamo četiri veza na našem molu za goste konobe, besplatno do 4 sata. Najavite se telefonom ili na VHF kanalu 17.', 'Yes. We have four berths on our pier for guests, free for up to four hours. Call ahead or hail us on VHF channel 17.', 'Ja. Für Gäste gibt es vier Liegeplätze an unserem Steg, bis zu vier Stunden kostenlos. Bitte vorher anrufen oder über UKW-Kanal 17 melden.', 8);
