insert into catch_items (site_id, name_hr, name_en, name_de, how_hr, how_en, how_de, price, sold_out, photo, sort) values ('konoba', 'Zubatac', 'Dentex', 'Zahnbrasse', 'za dvoje, s gradela', 'for two, grilled', 'für zwei, vom Grill', '72 €/kg', true, 'boat', 3);
insert into site_settings (site_id, catch_headline_hr, catch_headline_en, catch_headline_de, catch_note_hr, catch_note_en, catch_note_de, catch_by, catch_updated_at, closed_override, closed_note_hr, closed_note_en, closed_note_de) values ('konoba', 'Bura je stala, mreže su bile pune.', 'The bura dropped and the nets came in full.', 'Die Bora hat nachgelassen, die Netze waren voll.', 'Ovo je stiglo jutros s našeg broda. Kad nestane, nestane. Pitajte konobara što je na gradelama.', 'This came in on our boat this morning. When it''s gone, it''s gone. Ask your waiter what''s on the grill.', 'Das kam heute früh mit unserem Boot. Wenn es weg ist, ist es weg. Fragen Sie, was auf dem Grill liegt.', 'Luka', '2026-10-04T07:40:00+02:00', false, '', '', '');
